function saveConfig(){const j=currentJob(),form=$('configForm');if(!form)return true;const v=formValues(form);try{if(v.scmType==='Git'&&!v.repository.trim())throw Error('Enter the Git repository URL.');for(const key of ['cron','poll'])if(v[key]&&v[key].trim().split(/\s+/).length!==5&&!/^@(hourly|daily|weekly|monthly|yearly|midnight)$/.test(v[key]))throw Error('Use five cron fields or a supported @ schedule.');const env={};for(const line of v.env.split('\n').filter(x=>x.trim())){const m=line.match(/^([A-Za-z_][\w]*)=(.*)$/);if(!m)throw Error('Environment entries must use NAME=value.');env[m[1]]=m[2]}
 Object.assign(j,{description:v.description,disabled:v.disabled,env});Object.assign(j.config,{buildDiscarder:v.discard,parameterized:v.parameterized,agentLabel:v.label,scm:{type:v.scmType,url:v.repository,credentials:v.credentials,branch:v.branch},pipelineDefinition:v.definition,scriptPath:v.scriptPath,jenkinsfile:v.jenkinsfile,inputApproval:{enabled:v.approval,message:v.approvalMessage}});j.triggers=j.triggers.filter(t=>!['cron','pollSCM','webhook'].includes(t.type));if(v.cron)j.triggers.push({type:'cron',value:v.cron});if(v.poll)j.triggers.push({type:'pollSCM',value:v.poll});if(v.webhook)j.triggers.push({type:'webhook'});j.postBuildActions=j.postBuildActions.filter(a=>!['archiveArtifacts','junit'].includes(a.type));if(v.artifacts)j.postBuildActions.push({type:'archiveArtifacts',config:{patterns:v.artifacts}});if(v.junit)j.postBuildActions.push({type:'junit',config:{patterns:v.junit}});$('configError').textContent='';notice('Configuration saved in this simulation.');return true}catch(e){$('configError').textContent=e.message;$('configError').scrollIntoView({block:'center'});return false}}
function editParameter(index){if($('configForm')&&!saveConfig())return;const j=currentJob(),p=j.parameters[index]||{};showDialog('Parameter',dialogForm(field('Name','name',p.name||'')+field('Type','type',p.type||'String','text',['String','Boolean','Choice'])+field('Default value','default',String(p.default??''))+field('Choices (one per line)','choices',(p.choices||[]).join('\n'),'textarea')+field('Description','description',p.description||'')),v=>{validateName(v.name,j.parameters.map(p=>p.name),p.name);const choices=v.choices.split('\n').filter(Boolean);if(v.type==='Choice'&&!choices.length)throw Error('Add at least one choice.');const next={name:v.name,type:v.type,default:v.type==='Boolean'?v.default.toLowerCase()==='true':v.default,choices,description:v.description};if(index!==undefined&&j.parameters[index])j.parameters[index]=next;else j.parameters.push(next);j.config.parameterized=true;closeDialog();renderAll()})}
function renderBuildParameters(){const j=currentJob();if(!j)return renderDashboard();refs.main.innerHTML='<h1 class="pageTitle">Build with Parameters</h1><p class="description">'+esc(j.name)+'</p><form id="parameterForm"><div class="card"><div class="boxBody">'+(j.parameters.length?j.parameters.map((p,i)=>field(p.name,'p'+i,p.value??p.default??'',/boolean/i.test(p.type)?'checkbox':'text',/choice/i.test(p.type)?p.choices||[]:undefined)+'<p class="mutedNote">'+esc(p.description||'')+'</p>').join(''):'<div class="empty">No parameters configured.</div>')+'</div></div><div class="toolbar"><button type="submit" id="runParamsBtn" class="smallBtn primary">Build</button></div></form>';$('parameterForm').onsubmit=e=>{e.preventDefault();const v=formValues(e.target),params={};j.parameters.forEach((p,i)=>params[p.name]=v['p'+i]);startBuild(j.name,params)}}
function availableNode(j){const nodes=state.manage.nodes.filter(n=>n.online!==false&&Number(n.executors)>0&&(!j.config.agentLabel||(n.labels||[]).includes(j.config.agentLabel)));return nodes.find(n=>jobs().flatMap(x=>x.builds||[]).filter(b=>b.status==='running'&&b.node===n.name).length<Number(n.executors))}
function startBuild(name=activeJob,parameters={},queued=false){const j=jobByName(name);if(!j||j.disabled){notice('This project is disabled.');return}const node=availableNode(j);if((state.manage.nodes.length||j.config.agentLabel)&&!node){if(!queued)state.queue.push({id:'queue-'+Date.now(),job:j.name,parameters,reason:j.config.agentLabel?'Waiting for an available agent labeled '+j.config.agentLabel:'Waiting for an available executor'});notice('Build queued.');renderAll();return}const prior={job:activeJob,build:activeBuild,view:currentView};activeJob=j.name;const b={number:nextBuildNo(j),status:'running',time:'Now',duration:'0 sec',progress:0,console:'Started by user '+(state.user||'User')+'\n'+(node?'Running on '+node.name:'Lesson simulation — no agent execution')+'\n',cause:'Started by user '+(state.user||'User'),parameters:clone(parameters),node:node?.name,stages:clone(j.pipeline||[]).map((s,i)=>({...s,status:i?'':'running',log:''})),testResults:{total:0,passed:0,failed:0,tests:[]},artifacts:[],environment:{...j.env}};if(j.config.inputApproval?.enabled)b.approval={pending:true,message:j.config.inputApproval.message};j.builds.unshift(b);activeBuild=b.number;currentView='build';updateJobLasts(j);if(queued){activeJob=prior.job;activeBuild=prior.build;currentView=prior.view;renderHistory();renderOperations()}else renderAll();runBuildEvents(j,b)}
function runBuildEvents(j,b){const generation=ui.generation,token=seekToken;for(const [i,event] of (j.simulation?.events||[]).entries()){const delay=Math.max(0,Math.min(30000,Number(event.afterMs??(i+1)*700)));const timer=setTimeout(()=>{if(generation!==ui.generation||token!==seekToken||b.status!=='running'||!j.builds.includes(b)||!jobs().includes(j))return;if(b.approval?.pending){b.pendingEvents=b.pendingEvents||[];b.pendingEvents.push(clone(event));return}applyBuildEvent(j,b,event)},delay);ui.timers.push(timer)}}
function applyBuildEvent(j,b,event){if(event.console!==undefined)b.console+=(b.console?'\n':'')+event.console;for(const key of ['progress','duration','durationSeconds','status','stages','testResults','artifacts','logTimestamps'])if(event[key]!==undefined)b[key]=clone(event[key]);updateJobLasts(j);if(['configure','buildParameters','systemConfig','security','pipelineSyntax'].includes(currentView)){renderHistory();renderOperations()}else renderAll();if(b.status!=='running')drainQueue()}
function drainQueue(){const snapshot=[...state.queue];for(const q of snapshot){const j=jobByName(q.job);if(j&&availableNode(j)){state.queue.splice(state.queue.indexOf(q),1);startBuild(q.job,q.parameters||{},true)}}renderOperations()}
function checkStructure(text){const stack=[],pairs={'}':'{',')':'(',']':'['};let quote=null,comment=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(comment){if(c==='\n')comment=false;continue}if(quote){if(c==='\\'){i++;continue}if(c===quote)quote=null;continue}if(c==='/'&&n==='/'){comment=true;continue}if(c==='"'||c==="'"){quote=c;continue}if('{(['.includes(c))stack.push(c);if('})]'.includes(c)&&stack.pop()!==pairs[c])return 'Unbalanced delimiter near character '+(i+1)+'.'}return quote?'Unclosed quoted string.':stack.length?'Unclosed delimiter.':'Basic structure looks balanced. This does not compile Groovy or validate Jenkins steps.'}
function highlightedScript(text){return String(text).split('\n').map((line,i)=>'<span class="logLine"><span class="logNumber">'+(i+1)+'</span>'+esc(line).replace(/(&#39;.*?&#39;|&quot;.*?&quot;|'[^']*')/g,'<span style="color:var(--green)">$1</span>').replace(/\b(pipeline|agent|stages|stage|steps|post|environment|when|parallel|def|node|sh|echo)\b/g,'<b style="color:var(--link)">$1</b>')+'</span>').join('')}
